from __future__ import annotations

from dataclasses import dataclass
import re
from typing import Mapping
from urllib.parse import urlparse


_ALLOWED_PROFILES = {"aws", "onprem"}
_ALLOWED_ADDRESSING_STYLES = {"auto", "path", "virtual"}
_BUCKET_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{1,61}[A-Za-z0-9]$")


def _parse_bool(raw: str | None, *, default: bool) -> bool:
    if raw is None:
        return default

    normalized = raw.strip().lower()
    if normalized in {"1", "true", "yes", "y", "on"}:
        return True
    if normalized in {"0", "false", "no", "n", "off"}:
        return False

    raise ValueError(f"Invalid boolean value: {raw!r}")


def _parse_int(raw: str | None, *, default: int, field_name: str) -> int:
    if raw is None:
        return default

    try:
        value = int(raw)
    except ValueError as exc:
        raise ValueError(f"{field_name} must be an integer") from exc

    if value <= 0:
        raise ValueError(f"{field_name} must be greater than zero")

    return value


def _normalize_prefix(prefix: str) -> str:
    raw = prefix.strip().replace("\\", "/")
    if not raw:
        return ""

    if raw.startswith("/"):
        raise ValueError("key_prefix must not start with '/'")

    segments: list[str] = []
    for segment in raw.split("/"):
        if not segment or segment == ".":
            continue
        if segment == "..":
            raise ValueError("key_prefix must not contain '..'")
        segments.append(segment)

    return "/".join(segments)


@dataclass(frozen=True, slots=True)
class RuntimeStoreConfig:
    bucket_name: str
    region_name: str = "us-east-1"
    endpoint_url: str | None = None
    access_key_id: str | None = None
    secret_access_key: str | None = None
    session_token: str | None = None
    key_prefix: str = ""
    profile: str = "aws"
    addressing_style: str = "auto"
    connect_timeout_seconds: int = 5
    read_timeout_seconds: int = 30
    verify_tls: bool = True

    def __post_init__(self) -> None:
        bucket_name = self.bucket_name.strip()
        if not bucket_name:
            raise ValueError("bucket_name is required")
        if "/" in bucket_name or any(ch.isspace() for ch in bucket_name):
            raise ValueError("bucket_name must not contain '/' or whitespace")
        if not _BUCKET_PATTERN.match(bucket_name):
            raise ValueError("bucket_name format is invalid")
        object.__setattr__(self, "bucket_name", bucket_name)

        region_name = self.region_name.strip()
        if not region_name:
            raise ValueError("region_name is required")
        object.__setattr__(self, "region_name", region_name)

        profile = self.profile.strip().lower()
        if profile not in _ALLOWED_PROFILES:
            raise ValueError(
                f"profile must be one of {sorted(_ALLOWED_PROFILES)}"
            )
        object.__setattr__(self, "profile", profile)

        addressing_style = self.addressing_style.strip().lower()
        if addressing_style not in _ALLOWED_ADDRESSING_STYLES:
            raise ValueError(
                f"addressing_style must be one of {sorted(_ALLOWED_ADDRESSING_STYLES)}"
            )
        object.__setattr__(self, "addressing_style", addressing_style)

        normalized_prefix = _normalize_prefix(self.key_prefix)
        object.__setattr__(self, "key_prefix", normalized_prefix)

        if self.connect_timeout_seconds <= 0:
            raise ValueError("connect_timeout_seconds must be greater than zero")
        if self.read_timeout_seconds <= 0:
            raise ValueError("read_timeout_seconds must be greater than zero")

        endpoint_url = self.endpoint_url.strip() if self.endpoint_url else None
        if endpoint_url:
            parsed = urlparse(endpoint_url)
            if parsed.scheme not in {"http", "https"} or not parsed.netloc:
                raise ValueError("endpoint_url must be a valid http(s) URL")
            object.__setattr__(self, "endpoint_url", endpoint_url)

        if self.profile == "onprem" and not endpoint_url:
            raise ValueError("endpoint_url is required for onprem profile")

    @classmethod
    def from_env(
        cls,
        env: Mapping[str, str] | None = None,
        *,
        prefix: str = "RUNTIME_STORE_",
    ) -> "RuntimeStoreConfig":
        source = env or {}

        def get(name: str) -> str | None:
            return source.get(f"{prefix}{name}")

        return cls(
            bucket_name=(get("BUCKET") or "").strip(),
            region_name=(get("REGION") or "us-east-1").strip(),
            endpoint_url=(get("ENDPOINT_URL") or "").strip() or None,
            access_key_id=(get("ACCESS_KEY_ID") or "").strip() or None,
            secret_access_key=(get("SECRET_ACCESS_KEY") or "").strip() or None,
            session_token=(get("SESSION_TOKEN") or "").strip() or None,
            key_prefix=(get("KEY_PREFIX") or "").strip(),
            profile=(get("PROFILE") or "aws").strip(),
            addressing_style=(get("ADDRESSING_STYLE") or "auto").strip(),
            connect_timeout_seconds=_parse_int(
                get("CONNECT_TIMEOUT_SECONDS"),
                default=5,
                field_name="CONNECT_TIMEOUT_SECONDS",
            ),
            read_timeout_seconds=_parse_int(
                get("READ_TIMEOUT_SECONDS"),
                default=30,
                field_name="READ_TIMEOUT_SECONDS",
            ),
            verify_tls=_parse_bool(get("VERIFY_TLS"), default=True),
        )

    def as_boto3_client_kwargs(self) -> dict[str, object]:
        kwargs: dict[str, object] = {
            "region_name": self.region_name,
            "verify": self.verify_tls,
        }

        if self.endpoint_url:
            kwargs["endpoint_url"] = self.endpoint_url
        if self.access_key_id:
            kwargs["aws_access_key_id"] = self.access_key_id
        if self.secret_access_key:
            kwargs["aws_secret_access_key"] = self.secret_access_key
        if self.session_token:
            kwargs["aws_session_token"] = self.session_token

        return kwargs

    def redacted_dict(self) -> dict[str, object]:
        return {
            "bucket_name": self.bucket_name,
            "region_name": self.region_name,
            "endpoint_url": self.endpoint_url,
            "access_key_id": self.access_key_id,
            "secret_access_key": "***" if self.secret_access_key else None,
            "session_token": "***" if self.session_token else None,
            "key_prefix": self.key_prefix,
            "profile": self.profile,
            "addressing_style": self.addressing_style,
            "connect_timeout_seconds": self.connect_timeout_seconds,
            "read_timeout_seconds": self.read_timeout_seconds,
            "verify_tls": self.verify_tls,
        }
