from __future__ import annotations

from dataclasses import dataclass
import mimetypes
import re
from typing import Any, Mapping, Protocol, runtime_checkable

from .config import RuntimeStoreConfig


_METADATA_KEY_PATTERN = re.compile(r"^[a-z0-9][a-z0-9._-]*$")
_NOT_FOUND_CODES = {"404", "NoSuchKey", "NotFound", "NoSuchBucket"}


class RuntimeStoreError(Exception):
    """Base error for runtime object store operations."""


class ObjectStoreConfigurationError(RuntimeStoreError):
    """Raised when the object store cannot be configured."""


class ObjectNotFoundError(RuntimeStoreError):
    """Raised when an object cannot be found."""


@dataclass(frozen=True, slots=True)
class StoredObject:
    bucket: str
    key: str
    uri: str
    size: int | None = None
    e_tag: str | None = None
    content_type: str | None = None
    metadata: dict[str, str] | None = None


@runtime_checkable
class S3LikeClient(Protocol):
    def put_object(self, **kwargs: Any) -> Mapping[str, Any]: ...

    def get_object(self, **kwargs: Any) -> Mapping[str, Any]: ...

    def head_object(self, **kwargs: Any) -> Mapping[str, Any]: ...

    def delete_object(self, **kwargs: Any) -> Mapping[str, Any]: ...


def normalize_object_key(key: str, *, prefix: str = "") -> str:
    raw_key = key.strip().replace("\\", "/")
    if not raw_key:
        raise ValueError("key is required")
    if raw_key.startswith("/"):
        raise ValueError("key must be relative")

    segments: list[str] = []
    if prefix:
        prefix_segments = normalize_object_key(prefix).split("/")
        segments.extend(prefix_segments)

    for segment in raw_key.split("/"):
        if not segment or segment == ".":
            continue
        if segment == "..":
            raise ValueError("key must not contain '..'")
        segments.append(segment)

    if not segments:
        raise ValueError("key is required")

    return "/".join(segments)


def _normalize_metadata(metadata: Mapping[str, object] | None) -> dict[str, str]:
    if not metadata:
        return {}

    normalized: dict[str, str] = {}
    for raw_key, raw_value in metadata.items():
        key = str(raw_key).strip().lower()
        if not key:
            raise ValueError("metadata keys must not be empty")
        if not _METADATA_KEY_PATTERN.match(key):
            raise ValueError(
                "metadata keys must match the pattern [a-z0-9][a-z0-9._-]*"
            )
        if raw_value is None:
            raise ValueError(f"metadata value for {key!r} must not be None")
        normalized[key] = str(raw_value)

    return normalized


def _guess_content_type(key: str) -> str:
    guessed, _ = mimetypes.guess_type(key)
    return guessed or "application/octet-stream"


def _read_body(body: Any) -> bytes:
    if isinstance(body, bytes):
        return body
    if isinstance(body, bytearray):
        return bytes(body)
    if isinstance(body, memoryview):
        return body.tobytes()
    if hasattr(body, "read"):
        data = body.read()
        if isinstance(data, bytes):
            return data
        if isinstance(data, bytearray):
            return bytes(data)
        raise RuntimeStoreError("object body reader did not return bytes")
    raise RuntimeStoreError("unsupported response body type")


def _extract_error_code(error: Exception) -> str | None:
    response = getattr(error, "response", None)
    if isinstance(response, Mapping):
        raw = response.get("Error")
        if isinstance(raw, Mapping):
            code = raw.get("Code")
            if code is not None:
                return str(code)

    code = getattr(error, "code", None)
    if code is not None:
        return str(code)

    return None


def _is_not_found_error(error: Exception) -> bool:
    code = _extract_error_code(error)
    return code in _NOT_FOUND_CODES


def _build_s3_client(config: RuntimeStoreConfig) -> S3LikeClient:
    try:
        import boto3
        from botocore.config import Config as BotocoreConfig
    except ImportError as exc:
        raise ObjectStoreConfigurationError(
            "boto3 and botocore are required when no client is injected"
        ) from exc

    s3_options: dict[str, object] = {}
    if config.addressing_style != "auto":
        s3_options["addressing_style"] = config.addressing_style

    botocore_config = BotocoreConfig(
        connect_timeout=config.connect_timeout_seconds,
        read_timeout=config.read_timeout_seconds,
        retries={"max_attempts": 3, "mode": "standard"},
        s3=s3_options or None,
    )

    client_kwargs = config.as_boto3_client_kwargs()
    client_kwargs["config"] = botocore_config

    session = boto3.session.Session()
    return session.client("s3", **client_kwargs)


class RuntimeObjectStore:
    def __init__(
        self,
        config: RuntimeStoreConfig,
        client: S3LikeClient | None = None,
    ) -> None:
        self._config = config
        self._client = client or _build_s3_client(config)

    @property
    def config(self) -> RuntimeStoreConfig:
        return self._config

    @classmethod
    def from_env(
        cls,
        env: Mapping[str, str] | None = None,
        *,
        prefix: str = "RUNTIME_STORE_",
        client: S3LikeClient | None = None,
    ) -> "RuntimeObjectStore":
        return cls(RuntimeStoreConfig.from_env(env, prefix=prefix), client=client)

    def build_uri(self, key: str) -> str:
        normalized_key = normalize_object_key(key, prefix=self._config.key_prefix)
        return f"s3://{self._config.bucket_name}/{normalized_key}"

    def put_bytes(
        self,
        key: str,
        data: bytes | bytearray | memoryview,
        *,
        content_type: str | None = None,
        metadata: Mapping[str, object] | None = None,
        cache_control: str | None = None,
    ) -> StoredObject:
        if isinstance(data, bytes):
            payload = data
        elif isinstance(data, bytearray):
            payload = bytes(data)
        elif isinstance(data, memoryview):
            payload = data.tobytes()
        else:
            raise TypeError("data must be bytes-like")

        normalized_key = normalize_object_key(key, prefix=self._config.key_prefix)
        normalized_metadata = _normalize_metadata(metadata)
        resolved_content_type = content_type or _guess_content_type(normalized_key)

        request: dict[str, Any] = {
            "Bucket": self._config.bucket_name,
            "Key": normalized_key,
            "Body": payload,
            "ContentType": resolved_content_type,
        }
        if normalized_metadata:
            request["Metadata"] = normalized_metadata
        if cache_control:
            request["CacheControl"] = cache_control

        try:
            response = self._client.put_object(**request)
        except Exception as exc:  # pragma: no cover - client-specific behavior
            raise RuntimeStoreError(
                f"Failed to store object {normalized_key!r}"
            ) from exc

        return StoredObject(
            bucket=self._config.bucket_name,
            key=normalized_key,
            uri=self.build_uri(key),
            size=len(payload),
            e_tag=str(response.get("ETag")) if response.get("ETag") else None,
            content_type=resolved_content_type,
            metadata=normalized_metadata or None,
        )

    def get_bytes(self, key: str) -> bytes:
        normalized_key = normalize_object_key(key, prefix=self._config.key_prefix)
        try:
            response = self._client.get_object(
                Bucket=self._config.bucket_name,
                Key=normalized_key,
            )
        except Exception as exc:
            if _is_not_found_error(exc):
                raise ObjectNotFoundError(
                    f"Object not found: {self.build_uri(key)}"
                ) from exc
            raise RuntimeStoreError(
                f"Failed to fetch object {normalized_key!r}"
            ) from exc

        body = response.get("Body")
        return _read_body(body)

    def head(self, key: str) -> StoredObject:
        normalized_key = normalize_object_key(key, prefix=self._config.key_prefix)
        try:
            response = self._client.head_object(
                Bucket=self._config.bucket_name,
                Key=normalized_key,
            )
        except Exception as exc:
            if _is_not_found_error(exc):
                raise ObjectNotFoundError(
                    f"Object not found: {self.build_uri(key)}"
                ) from exc
            raise RuntimeStoreError(
                f"Failed to inspect object {normalized_key!r}"
            ) from exc

        metadata = response.get("Metadata") or None
        normalized_metadata = (
            {str(k): str(v) for k, v in metadata.items()} if metadata else None
        )

        return StoredObject(
            bucket=self._config.bucket_name,
            key=normalized_key,
            uri=self.build_uri(key),
            size=int(response["ContentLength"])
            if response.get("ContentLength") is not None
            else None,
            e_tag=str(response.get("ETag")) if response.get("ETag") else None,
            content_type=str(response.get("ContentType"))
            if response.get("ContentType")
            else None,
            metadata=normalized_metadata,
        )

    def exists(self, key: str) -> bool:
        try:
            self.head(key)
        except ObjectNotFoundError:
            return False
        return True

    def delete(self, key: str, *, missing_ok: bool = True) -> bool:
        normalized_key = normalize_object_key(key, prefix=self._config.key_prefix)
        try:
            self._client.delete_object(
                Bucket=self._config.bucket_name,
                Key=normalized_key,
            )
        except Exception as exc:
            if missing_ok and _is_not_found_error(exc):
                return False
            if _is_not_found_error(exc):
                raise ObjectNotFoundError(
                    f"Object not found: {self.build_uri(key)}"
                ) from exc
            raise RuntimeStoreError(
                f"Failed to delete object {normalized_key!r}"
            ) from exc

        return True
