from __future__ import annotations

from pathlib import Path
import sys

import pytest

ROOT = Path(__file__).resolve().parents[1] / "src"
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from runtime_store import (  # noqa: E402
    ObjectNotFoundError,
    RuntimeObjectStore,
    RuntimeStoreConfig,
    normalize_object_key,
)


class FakeClientError(Exception):
    def __init__(self, code: str, message: str = "client error") -> None:
        super().__init__(message)
        self.response = {"Error": {"Code": code, "Message": message}}


class FakeBody:
    def __init__(self, data: bytes) -> None:
        self._data = data

    def read(self) -> bytes:
        return self._data


class FakeS3Client:
    def __init__(self) -> None:
        self._objects: dict[tuple[str, str], dict[str, object]] = {}

    def put_object(self, **kwargs):
        bucket = kwargs["Bucket"]
        key = kwargs["Key"]
        body = bytes(kwargs["Body"])
        record = {
            "Body": body,
            "ContentType": kwargs.get("ContentType"),
            "Metadata": dict(kwargs.get("Metadata") or {}),
            "CacheControl": kwargs.get("CacheControl"),
            "ETag": f'"etag-{len(body)}"',
        }
        self._objects[(bucket, key)] = record
        return {"ETag": record["ETag"]}

    def get_object(self, **kwargs):
        bucket = kwargs["Bucket"]
        key = kwargs["Key"]
        try:
            record = self._objects[(bucket, key)]
        except KeyError as exc:
            raise FakeClientError("NoSuchKey") from exc

        return {
            "Body": FakeBody(record["Body"]),
            "ContentLength": len(record["Body"]),
            "ContentType": record["ContentType"],
            "Metadata": record["Metadata"],
            "ETag": record["ETag"],
        }

    def head_object(self, **kwargs):
        bucket = kwargs["Bucket"]
        key = kwargs["Key"]
        try:
            record = self._objects[(bucket, key)]
        except KeyError as exc:
            raise FakeClientError("404") from exc

        return {
            "ContentLength": len(record["Body"]),
            "ContentType": record["ContentType"],
            "Metadata": record["Metadata"],
            "ETag": record["ETag"],
        }

    def delete_object(self, **kwargs):
        bucket = kwargs["Bucket"]
        key = kwargs["Key"]
        try:
            del self._objects[(bucket, key)]
        except KeyError as exc:
            raise FakeClientError("NoSuchKey") from exc
        return {}


def build_store(**config_overrides) -> RuntimeObjectStore:
    config = RuntimeStoreConfig(
        bucket_name="runtime-artifacts",
        key_prefix="req-001/runtime",
        profile="onprem",
        endpoint_url="https://objects.internal.example",
        **config_overrides,
    )
    return RuntimeObjectStore(config, client=FakeS3Client())


def test_runtime_store_round_trip_with_metadata_and_prefix() -> None:
    store = build_store()

    stored = store.put_bytes(
        "reports/final.json",
        b'{"status":"ok"}',
        metadata={"Trace_Id": "req-001", "source": "kit"},
    )

    assert stored.bucket == "runtime-artifacts"
    assert stored.key == "req-001/runtime/reports/final.json"
    assert stored.uri == "s3://runtime-artifacts/req-001/runtime/reports/final.json"
    assert stored.content_type == "application/json"
    assert stored.metadata == {"trace_id": "req-001", "source": "kit"}
    assert store.exists("reports/final.json") is True
    assert store.get_bytes("reports/final.json") == b'{"status":"ok"}'

    head = store.head("reports/final.json")
    assert head.size == len(b'{"status":"ok"}')
    assert head.e_tag == '"etag-15"'
    assert head.metadata == {"trace_id": "req-001", "source": "kit"}

    assert store.delete("reports/final.json") is True
    assert store.exists("reports/final.json") is False


def test_missing_object_raises_domain_error() -> None:
    store = build_store()

    with pytest.raises(ObjectNotFoundError):
        store.get_bytes("missing/file.txt")

    with pytest.raises(ObjectNotFoundError):
        store.head("missing/file.txt")

    with pytest.raises(ObjectNotFoundError):
        store.delete("missing/file.txt", missing_ok=False)

    assert store.delete("missing/file.txt", missing_ok=True) is False


def test_normalize_object_key_rejects_escape_and_absolute_paths() -> None:
    assert (
        normalize_object_key("nested\\path\\file.txt", prefix="runtime/output")
        == "runtime/output/nested/path/file.txt"
    )

    with pytest.raises(ValueError):
        normalize_object_key("/absolute/file.txt")

    with pytest.raises(ValueError):
        normalize_object_key("../escape.txt")

    with pytest.raises(ValueError):
        normalize_object_key("safe/../../escape.txt")


